CREATE TABLE IF NOT EXISTS v213_checkins(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),secret TEXT NOT NULL,title TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),ends_at TIMESTAMPTZ NOT NULL,closed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS v213_checkins_class ON v213_checkins(class_id,created_at DESC);
CREATE TABLE IF NOT EXISTS v213_receipts(session_id TEXT REFERENCES v213_checkins(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,submitted_at TIMESTAMPTZ,reviewed_status TEXT CHECK(reviewed_status IN('present','late','leave','absent')),PRIMARY KEY(session_id,user_id));
CREATE TABLE IF NOT EXISTS v213_counts(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES v213_checkins(id) ON DELETE CASCADE,actor_id TEXT NOT NULL REFERENCES users(id),estimated INTEGER CHECK(estimated BETWEEN 0 AND 500),confirmed INTEGER NOT NULL CHECK(confirmed BETWEEN 0 AND 500),note TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
